<?php include "../auth/cek_login.php";include "../koneksi.php";$p=mysqli_query($conn,"SELECT * FROM pelanggan");$b=mysqli_query($conn,"SELECT * FROM barang WHERE stok>0");if(isset($_POST['simpan'])){$kode='TRX'.date('YmdHis');$pid=$_POST['pelanggan'];$bid=$_POST['barang'];$jumlah=(int)$_POST['jumlah'];$sewa=$_POST['tanggal_sewa'];$kembali=$_POST['tanggal_kembali'];$br=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM barang WHERE id=$bid"));$hari=max(1,(strtotime($kembali)-strtotime($sewa))/86400);$subtotal=$hari*$br['harga_sewa']*$jumlah;if($jumlah>$br['stok'])die('Stok tidak cukup');mysqli_query($conn,"INSERT INTO transaksi(kode_transaksi,id_pelanggan,tanggal_sewa,tanggal_rencana_kembali,total_harga) VALUES('$kode',$pid,'$sewa','$kembali',$subtotal)");$tid=mysqli_insert_id($conn);mysqli_query($conn,"INSERT INTO detail_transaksi(id_transaksi,id_barang,jumlah,harga_sewa,subtotal) VALUES($tid,$bid,$jumlah,{$br['harga_sewa']},$subtotal)");mysqli_query($conn,"UPDATE barang SET stok=stok-$jumlah WHERE id=$bid");header("Location:index.php");exit;}?><!doctype html><html><head><title>Transaksi Baru</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="content"><h1>Transaksi Penyewaan</h1><form method="post"><label>Pelanggan</label><select name="pelanggan" required><option value="">Pilih</option><?php while($x=mysqli_fetch_assoc($p)):?><option value="<?=$x['id']?>"><?=$x['nama']?></option><?php endwhile;?></select><label>Barang</label><select name="barang" required><?php while($x=mysqli_fetch_assoc($b)):?><option value="<?=$x['id']?>"><?=$x['nama_barang']?> - Rp <?=number_format($x['harga_sewa'])?> (stok <?=$x['stok']?>)</option><?php endwhile;?></select><input type="date" name="tanggal_sewa" value="<?=date('Y-m-d')?>" required><input type="date" name="tanggal_kembali" value="<?=date('Y-m-d',strtotime('+1 day'))?>" required><input type="number" name="jumlah" min="1" value="1" required><button name="simpan">Simpan Transaksi</button></form></div></body></html>